def _mk(d):
    os.makedirs(d, exist_ok=True)
    return d


def hat(c):
    """Piecewise-linear basis of clarity (KNOTS); each row sums to one."""
    c = np.clip(np.asarray(c, np.float64), 0.0, 1.0)
    return np.stack([np.clip(1 - np.abs(c - k) / 0.25, 0.0, None) for k in KNOTS], 1)


def zrel(p, th):
    return F4.logit(p) - F4.logit(th)


def conf_X5(p, p0, c, th):
    z, z0 = zrel(p, th), zrel(p0, th)
    s = (z >= 0).astype(np.float64)
    sign = np.where(s > 0, 1.0, -1.0)
    H = hat(c)
    return np.concatenate([H, H * np.abs(z)[:, None], H * s[:, None], H * ((z - z0) * sign)[:, None]], 1)


def conf_X5_free(p, p0, c, th):
    """Ablation: the label-free margin toward the (with-label) decision, side and clarity only."""
    z, z0 = zrel(p, th), zrel(p0, th)
    s = (z >= 0).astype(np.float64)
    sign = np.where(s > 0, 1.0, -1.0)
    H = hat(c)
    return np.concatenate([H, H * (z0 * sign)[:, None], H * s[:, None]], 1)


def notif_X5(p, p0, c, th, F, w=None):
    z, z0 = zrel(p, th), zrel(p0, th)
    H = hat(c)
    parts = [H, H * z[:, None], H * (z - z0)[:, None]]
    if w is not None:
        parts.append(F4.logit(w)[:, None])
    parts.append(np.asarray(F, np.float64).reshape(len(z), -1))
    return np.concatenate(parts, 1)


def _lr0(X, y):
    from sklearn.linear_model import LogisticRegression
    m = LogisticRegression(C=1.0, max_iter=20000, fit_intercept=False).fit(X, y)
    return {"coef": [float(x) for x in m.coef_[0]], "intercept": 0.0}


def load_models():
    return json.load(open(os.path.join(OUT, "models5.json")))


def last_line(text):
    return text.split("\n")[-1]


def auroc(score, right):
    score, right = np.asarray(score, np.float64), np.asarray(right, bool)
    if right.all() or not right.any():
        return None
    order = np.argsort(score, kind="mergesort")
    ranks = np.empty(len(score))
    ranks[order] = np.arange(1, len(score) + 1)
    for v in np.unique(score):                                   # average ranks of ties
        m = score == v
        if m.sum() > 1:
            ranks[m] = ranks[m].mean()
    npos = right.sum()
    return float((ranks[right].sum() - npos * (npos + 1) / 2) / (npos * (len(score) - npos)))


# ------------------------------------------------------------------------------------------------ texts

class TrainNoLab(AC.MultiEdited):
    """The main system's training text (step 2c decoupled edits) without the event and movement labels."""

    def point(self, r, k):
        tr, sc, tags, snd = super().point(r, k)
        return tr, sc, tags, [s for s in snd if s[0] not in DROP]


class NaturalNoLab(C.Context):
    """The standard natural text (as the stored natural dev forward) without the event and movement labels."""

    def point(self, r, k):
        tr, sc, tags, snd = super().point(r, k)
        return tr, sc, tags, [s for s in snd if s[0] not in DROP]


def dev_nolab_context(groups, rows_by):
    """Step 1's matched "none" inputs (version 2's, event labels removed) without the movement labels as well."""
    M = G.matched_context(C.Context)

    class NoLab(M):
        def point(self, r, k):
            tr, sc, tags, snd = super().point(r, k)
            return tr, sc, tags, [s for s in snd if s[0] not in DROP]

    return NoLab("dev", groups, "none", rows_by, final=False)


def train_used():
    """(rows_by, the version 4-5 training windows in train order): clean windows of clean units and the noisy windows
    with decoupled labels (their noisy audio)."""
    rows, wins = FIX.train_rows()
    zz = np.load(F4.NOISY_NPZ)
    reg = dict(zip(zz["ids"].astype(str), zz["regime"].astype(str)))
    a = FIX.load_assign()
    used = []
    for w in wins:
        noisy_unit = w["part"] in FIX.NOISY_PARTS and a["unit_db"].get(w["unit"], 0) > 0
        if noisy_unit and reg.get(w["id"]) != "decoupled":
            continue
        used.append(w)
    return {(r["unit"], r["version"]): r for r in rows}, used


def train_texts(rows_by, used):
    edits = {k: [tuple(e) for e in v] for k, v in json.load(open(FIX.EDITS)).items()}
    ctx, ctx0 = AC.MultiEdited("train", edits), TrainNoLab("train", edits)
    out = {}
    for w in used:
        r = rows_by[w["key"]]
        t1, asks = ctx.situation(r, w["k"], "full")
        t0, asks0 = ctx0.situation(r, w["k"], "full")
        assert asks == asks0, w["id"]
        out[w["id"]] = (t1, t0, asks)
    return out


def dev_grid():
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins = [w for w in D.windows_of(rows, "dev") if (w["unit"], w["version"], w["k"]) in keys]
    return rows, rows_by, groups, wins


# ------------------------------------------------------------------------------------------------ smoke

def smoke():
    lines = []

    def say(*a):
        s = " ".join(str(x) for x in a)
        print(s, flush=True)
        lines.append(s)

    rows_by, used = train_used()
    texts = train_texts(rows_by, used)
    changed = [w for w in used if texts[w["id"]][0] != texts[w["id"]][1]]
    unchanged = [w for w in used if texts[w["id"]][0] == texts[w["id"]][1]]
    say(f"train: {len(used)} windows used (versions 4-5 mix), label-free text changes for {len(changed)}, "
        f"unchanged {len(unchanged)} (floor sample, every 8th: {len(unchanged[::8])})")
    by_part = collections.Counter((w["part"], texts[w["id"]][0] != texts[w["id"]][1]) for w in used)
    say("   by (part, changed):", dict(sorted(by_part.items())))
    removed = collections.Counter()
    header = "Earlier, oldest first:"
    for w in changed:
        a_, b_ = texts[w["id"]][0].split("\n"), texts[w["id"]][1].split("\n")
        gone = [x for x in a_ if x not in b_]
        assert all(" detected sound: " in x or x == header for x in gone), (w["id"], gone)
        if header in gone:                            # the history header goes only when no history line is left
            assert not any(x.startswith("[") for x in b_), w["id"]
            removed["(history header, history left empty)"] += 1
        assert [x for x in a_ if x not in gone] == b_, w["id"]
        for x in gone:
            if x != header:
                removed[x.split(" detected sound: ")[1].split(",")[0]] += 1
    say("   removed lines (label lines by class; the history header when nothing else was left; the rest of the text "
        "is unchanged):", dict(removed.most_common()))
    ex = [w for w in changed if w["part"] in ("r_hear", "s_move")][:2]
    for w in ex:
        say(f"=== train {w['id']} with labels\n{texts[w['id']][0]}\n=== without\n{texts[w['id']][1]}")
    lastl = collections.Counter(last_line(texts[w["id"]][0]).split(":")[0] for w in used if w["gold"].get("R"))
    say("   R rows: last-line openings", dict(lastl.most_common(6)))
    # row order: version 4's cross-fit rows (all 2c questions with a gold answer, S then R)
    z = np.load(FIX.F2C)
    v4 = np.load(os.path.join(F4.OUT, "crossfit.npz"))
    ids, q_win, q_task, q_gold = z["ids"].astype(str), z["q_win"], z["q_task"].astype(str), z["q_gold"].astype(int)
    wins_order = np.concatenate([ids[q_win[(q_task == q) & (q_gold >= 0)]] for q in ("S", "R")])
    assert np.array_equal(wins_order, v4["row_win"].astype(str)), "row order differs from version 4"
    use4 = ~(v4["row_noisy"] & (v4["row_regime"] == "natural"))
    usedset = {w["id"] for w in used}
    assert {str(x) for x in v4["row_win"][use4]} <= usedset, "a row kept for fitting is not on a used window"
    say(f"row order: version 4's {len(wins_order)} rows reproduced; rows kept for fitting {int(use4.sum())}, all on used "
        f"windows")
    # dev grid: label-free texts against step 1's "none" texts
    rows_d, rows_by_d, groups, gw = dev_grid()
    ctx0 = dev_nolab_context(groups, rows_by_d)
    gof = {g["unit"]: g["part"] for g in groups}
    ref = np.load(f"{FIX.REL_DEV}/dclean/l1_none.npz")
    ref_sha = {str(i): str(h) for i, h in zip(ref["ids"], ref["text_sha"])}
    same = collections.Counter()
    exd = None
    for w in gw:
        t0, _ = ctx0.situation(rows_by_d[(w["unit"], w["version"])], w["k"], "full")
        eq = G.sha(t0) == ref_sha[w["id"]]
        same[(gof[w["unit"]], eq)] += 1
        if not eq and exd is None:
            exd = (w["id"], t0)
    say("dev grid: label-free text equal to step 1's 'none' text (part, equal):", dict(sorted(same.items())))
    if exd:
        say(f"=== dev {exd[0]} label-free (differs from 'none' by the movement labels)\n{exd[1]}")
    # natural dev
    ctxn, ctxn0 = C.Context("dev"), NaturalNoLab("dev")
    nchg = collections.Counter()
    for w in D.windows_of(rows_d, "dev"):
        r = rows_by_d[w["key"]]
        nchg[w["part"], ctxn.situation(r, w["k"], "full")[0] != ctxn0.situation(r, w["k"], "full")[0]] += 1
    say("natural dev: label-free text changes (part, changed):", dict(sorted(nchg.items())))
    _mk(OUT)
    open(os.path.join(OUT, "smoke.txt"), "w", encoding="utf-8").write("\n".join(lines) + "\n")
    print(f"-> {OUT}/smoke.txt", flush=True)


# ------------------------------------------------------------------------------------------------ forward

def _official_z(states, sm, sx, q_task, ro, th):
    """Official main-system z (logit p - logit th) per question."""
    import p1v4_readout_2d as R2D
    out = np.zeros(len(q_task))
    for q in ("S", "R"):
        m = np.where(q_task == q)[0]
        if not len(m):
            continue
        X = R2D.design(states[m], sm[m], sx[m])
        lg = ((X - ro[q]["mu"]) / ro[q]["sd"]) @ ro[q]["w"] + float(ro[q]["b"])
        out[m] = lg - F4.logit(th[q])
    return out


def _floor(z_new, z_old):
    d = np.abs(np.asarray(z_new) - np.asarray(z_old))
    return {"n": int(len(d)), "median": float(np.median(d)), "p95": float(np.quantile(d, 0.95)),
            "max": float(d.max())}


FLOOR_STOP = 0.25
FLOOR_REPORT = 0.1


class StoredTrain:
    """The stored with-label train forwards (step 2c clean, version-1 noisy); every npz member is read once (a lazy
    NpzFile re-reads the whole member on each access)."""

    def __init__(self):
        z2c, e, zz = np.load(FIX.F2C), np.load(FIX.FSEC), np.load(F4.NOISY_NPZ)
        c_ids, c_qwin, c_task = z2c["ids"].astype(str), z2c["q_win"], z2c["q_task"].astype(str)
        n_ids, n_qwin, n_task = zz["ids"].astype(str), zz["q_win"], zz["q_task"].astype(str)
        self.c_states, self.c_sm, self.c_sx = z2c["states"], e["sec_mean"], e["sec_max"]
        self.n_states, self.n_sm, self.n_sx = zz["states"], zz["sec_mean"], zz["sec_max"]
        self.pos2c = {(i, q): j for j, (i, q) in enumerate(zip(c_ids[c_qwin], c_task))}
        self.posn = {(i, q): j for j, (i, q) in enumerate(zip(n_ids[n_qwin], n_task))}
        self.wpos = {i: n for n, i in enumerate(c_ids)}
        self.npos = {i: n for n, i in enumerate(n_ids)}

    def ears(self, win):
        sm = np.stack([self.n_sm[self.npos[w]] if w in self.npos else self.c_sm[self.wpos[w]] for w in win])
        sx = np.stack([self.n_sx[self.npos[w]] if w in self.npos else self.c_sx[self.wpos[w]] for w in win])
        return sm, sx

    def states(self, win, tasks):
        return np.stack([self.n_states[self.posn[(w, q)]] if w in self.npos else self.c_states[self.pos2c[(w, q)]]
                         for w, q in zip(win, tasks)])


def _pairs(nl, sel, st, ro, th):
    """Official z of the label-free forward and of the stored with-label forward, for the questions sel of nl."""
    win, q_t = nl["win_id"][sel], nl["q_task"][sel]
    sm, sx = st.ears(win)
    z_new = _official_z(nl["states"][sel], sm, sx, q_t, ro, th)
    z_old = _official_z(st.states(win, q_t), sm, sx, q_t, ro, th)
    return z_new, z_old, np.array([w in st.npos for w in win])


def _train_check(st, floor_ids, changed_ids, ro, th):
    """Floor on the unchanged-text windows forwarded so far, and |z - z0| on every 8th changed window so far."""
    nl = load_train_nolab()
    sel_f = np.array([j for j, w in enumerate(nl["win_id"]) if w in floor_ids], int)
    sel_c = np.array([j for j, w in enumerate(nl["win_id"]) if w in changed_ids], int)[::8]
    out = {"floor clean": None, "floor noisy": None, "changed windows |z - z0| (every 8th)": None}
    if len(sel_f):
        zn, zo, isn = _pairs(nl, sel_f, st, ro, th)
        out["floor clean"] = _floor(zn[~isn], zo[~isn]) if (~isn).any() else None
        out["floor noisy"] = _floor(zn[isn], zo[isn]) if isn.any() else None
    if len(sel_c):
        zn, zo, _ = _pairs(nl, sel_c, st, ro, th)
        out["changed windows |z - z0| (every 8th)"] = _floor(zn, zo)
    return out


def _gate(name, stats, log):
    """Code-review rule (written before the run): stop above FLOOR_STOP, report above FLOOR_REPORT."""
    if stats is None:
        return
    if stats["p95"] > FLOOR_STOP:
        json.dump(log, open(os.path.join(OUT, "forward_log.json"), "w"), indent=1)
        raise SystemExit(f"{name}: floor 95th percentile {stats['p95']:.3f} > {FLOOR_STOP}; stopped")
    if stats["p95"] > FLOOR_REPORT:
        log.setdefault("floor_notes", []).append(f"{name}: 95th percentile {stats['p95']:.3f} > {FLOOR_REPORT}")


def _save(path, z):
    tmp = path[:-4] + ".tmp.npz"
    np.savez(tmp, **z)
    os.replace(tmp, path)


def forward():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    t_all = time.time()
    ro, th = R2D.load_2d(), F4.main_th()
    log = {"rule": f"stop if the 95th percentile |dz| on unchanged-text windows > {FLOOR_STOP}, report if > "
                   f"{FLOOR_REPORT}; dev windows whose text equals step 1's 'none' text must reproduce it exactly"}
    model = F3._model()
    # 1. dev grid (batch 1, as step 1) and its exact-reproduction gate
    rows_d, rows_by_d, groups, gw = dev_grid()
    ctx0 = dev_nolab_context(groups, rows_by_d)
    part_of = {g["unit"]: g["part"] for g in groups}
    t0s = {w["id"]: ctx0.situation(rows_by_d[(w["unit"], w["version"])], w["k"], "full") for w in gw}
    log["dev_floor"] = {}
    for lv in LEVELS:
        path = os.path.join(_mk(os.path.join(OUT, "dev", lv)), "l1_nolab.npz")
        ref = dict(np.load(f"{FIX.REL_DEV}/{lv}/l1_none.npz"))
        rpos = {str(i): n for n, i in enumerate(ref["ids"])}
        if not os.path.exists(path):
            if lv == "dclean":
                paths = {w["id"]: w["path"] for w in gw}
            else:
                import p1v4_noise_final as NF
                NF.patch_folders()
                want = {w["id"] for w in gw}
                paths = {w["id"]: w["path"] for w in D.windows_of(D.load_rows(f"dev_{lv}"), f"dev_{lv}")
                         if w["id"] in want}
            items = [F3._item(w, *t0s[w["id"]], paths[w["id"]]) for w in gw]
            z, secs = F3._forward(model, items, 1)
            idx = [rpos[str(i)] for i in z["ids"]]
            z["sec_mean"], z["sec_max"] = ref["sec_mean"][idx], ref["sec_max"][idx]
            z["parts"] = np.array([part_of[str(u)] for u in z["units"]])
            z["text_sha"] = np.array([G.sha(t0s[str(i)][0]) for i in z["ids"]])
            _save(path, z)
            print(f"dev {lv} label-free: {len(items)} windows, {secs:.0f} s", flush=True)
        z = dict(np.load(path))
        assert np.array_equal(z["ids"].astype(str), ref["ids"].astype(str)), "dev window order differs from step 1"
        assert np.array_equal(z["q_win"], ref["q_win"]) and np.array_equal(z["q_task"], ref["q_task"]), \
            "dev questions differ from step 1"
        eqw = np.array([a == b for a, b in zip(z["text_sha"].astype(str), ref["text_sha"].astype(str))])
        eqq = eqw[z["q_win"]]
        zn = _official_z(z["states"], z["sec_mean"][z["q_win"]], z["sec_max"][z["q_win"]], z["q_task"].astype(str),
                         ro, th)
        zr = _official_z(ref["states"], ref["sec_mean"][ref["q_win"]], ref["sec_max"][ref["q_win"]],
                         ref["q_task"].astype(str), ro, th)
        log["dev_floor"][lv] = {"windows_equal_text": int(eqw.sum()), "windows": int(len(eqw)),
                                **_floor(zn[eqq], zr[eqq]),
                                "changed questions |z_none - z0|": _floor(zn[~eqq], zr[~eqq]) if (~eqq).any() else None}
        if log["dev_floor"][lv]["max"] > 1e-6:
            json.dump(log, open(os.path.join(OUT, "forward_log.json"), "w"), indent=1)
            raise SystemExit(f"dev {lv}: equal-text windows do not reproduce step 1 exactly: {log['dev_floor'][lv]}")
    print("dev floor:", json.dumps(log["dev_floor"]), flush=True)
    # 2. natural dev (batch 8 and window order of the stored natural forward)
    path = os.path.join(OUT, "dev", "natural_nolab.npz")
    zs = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    wins_n = D.windows_of(rows_d, "dev")
    assert [w["id"] for w in wins_n] == list(zs["ids"].astype(str)), "natural window order differs"
    ctxn, ctxn0 = C.Context("dev"), NaturalNoLab("dev")
    tn = {w["id"]: (ctxn.situation(rows_by_d[w["key"]], w["k"], "full")[0],
                    ctxn0.situation(rows_by_d[w["key"]], w["k"], "full")) for w in wins_n}
    if not os.path.exists(path):
        items = [F3._item(w, *tn[w["id"]][1], w["path"]) for w in wins_n]
        z, secs = F3._forward(model, items, 8)
        z["changed"] = np.array([tn[str(i)][0] != tn[str(i)][1][0] for i in z["ids"]])
        _save(path, z)
        print(f"natural dev label-free: {len(items)} windows, {secs:.0f} s", flush=True)
    z = dict(np.load(path))
    sec = R2D.Sec()
    assert np.array_equal(z["q_task"], zs["q_task"]) and np.array_equal(z["q_win"], zs["q_win"])
    rws = sec.rows(z["ids"][z["q_win"]])
    zn = _official_z(z["states"], sec.sm[rws], sec.sx[rws], z["q_task"].astype(str), ro, th)
    rws_s = sec.rows(zs["ids"][zs["q_win"]])
    zr = _official_z(zs["states"], sec.sm[rws_s], sec.sx[rws_s], zs["q_task"].astype(str), ro, th)
    unch = ~z["changed"][z["q_win"]]
    log["natural_floor"] = _floor(zn[unch], zr[unch]) if unch.any() else None
    log["natural changed questions |z - z0|"] = _floor(zn[~unch], zr[~unch]) if (~unch).any() else None
    print("natural floor:", log["natural_floor"], "| changed:", log["natural changed questions |z - z0|"], flush=True)
    _gate("natural", log["natural_floor"], log)
    # 3. train (batch 8, train order, resumable chunks written atomically)
    rows_by, used = train_used()
    texts = train_texts(rows_by, used)
    noisy = json.load(open(os.path.join(FIX.FIX, "noisy_windows.json")))
    changed_ids = {w["id"] for w in used if texts[w["id"]][0] != texts[w["id"]][1]}
    unchanged = [w for w in used if w["id"] not in changed_ids]
    floor_ids = {w["id"] for w in unchanged[::8]}
    todo = [w for w in used if w["id"] in changed_ids or w["id"] in floor_ids]
    json.dump({"changed": [w["id"] for w in used if w["id"] in changed_ids], "floor": sorted(floor_ids),
               "todo": [w["id"] for w in todo], "last_line": {w["id"]: last_line(texts[w["id"]][0]) for w in used}},
              open(os.path.join(_mk(OUT), "train_index.json"), "w"))
    st = StoredTrain()
    for ci in range(0, len(todo), CHUNK):
        path = os.path.join(OUT, f"train_nolab_{ci // CHUNK:02d}.npz")
        if os.path.exists(path):
            print(f"{path}: exists, skipped", flush=True)
            continue
        items = [F3._item(w, texts[w["id"]][1], texts[w["id"]][2],
                          noisy[w["id"]]["path"] if w["id"] in noisy else w["path"]) for w in todo[ci:ci + CHUNK]]
        z, secs = F3._forward(model, items, 8)
        _save(path, z)
        print(f"train label-free chunk {ci // CHUNK}: {len(items)} windows, {secs:.0f} s "
              f"({time.time() - t_all:.0f} s in all)", flush=True)
        if ci == 0:
            chk = _train_check(st, floor_ids, changed_ids, ro, th)
            log["train_after_chunk_0"] = chk
            print("train check after chunk 0:", json.dumps(chk), flush=True)
            _gate("train clean, chunk 0", chk["floor clean"], log)
            _gate("train noisy, chunk 0", chk["floor noisy"], log)
    chk = _train_check(st, floor_ids, changed_ids, ro, th)
    log["train"] = chk
    print("train check:", json.dumps(chk), flush=True)
    _gate("train clean", chk["floor clean"], log)
    _gate("train noisy", chk["floor noisy"], log)
    log["gates_passed"] = True
    log["seconds"] = time.time() - t_all
    json.dump(log, open(os.path.join(OUT, "forward_log.json"), "w"), indent=1)


def load_train_nolab():
    """The train label-free chunks concatenated: states, q_task, q_gold, win_id per question; ids per window."""
    S_, T_, G_, W_, I_ = [], [], [], [], []
    i = 0
    while os.path.exists(os.path.join(OUT, f"train_nolab_{i:02d}.npz")):
        z = np.load(os.path.join(OUT, f"train_nolab_{i:02d}.npz"))
        ids = z["ids"].astype(str)
        S_.append(z["states"])
        T_.append(z["q_task"].astype(str))
        G_.append(z["q_gold"].astype(int))
        W_.append(ids[z["q_win"]])
        I_.append(ids)
        i += 1
    return {"states": np.concatenate(S_), "q_task": np.concatenate(T_), "q_gold": np.concatenate(G_),
            "win_id": np.concatenate(W_), "ids": np.concatenate(I_)}


# ------------------------------------------------------------------------------------------------ crossfit

def words_fit(lines, y):
    from sklearn.feature_extraction.text import TfidfVectorizer
    from sklearn.linear_model import LogisticRegression
    vec = TfidfVectorizer(ngram_range=(1, 2), min_df=2, lowercase=True)
    X = vec.fit_transform(lines)
    clf = LogisticRegression(C=1.0, max_iter=5000).fit(X, y)
    return vec, clf


def words_p(model, lines):
    vec, clf = model
    return clf.predict_proba(vec.transform(lines))[:, 1]


def raw_logits(lin, X):
    """The fold model's unclipped logits (RO.predict returns probabilities)."""
    import torch
    with torch.no_grad():
        out = [lin(torch.from_numpy(X[j:j + 8192]).cuda().float()).squeeze(-1).cpu().numpy()
               for j in range(0, len(X), 8192)]
    return np.concatenate(out).astype(np.float64)


def _ratio(a, b):
    return float(np.mean(np.abs(a)) / np.mean(np.abs(b)))


def crossfit():
    import torch
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    D.gpu_guard()
    t0 = time.time()
    flog = json.load(open(os.path.join(OUT, "forward_log.json")))
    assert flog.get("gates_passed"), "the forward's gates did not pass"
    v4 = np.load(os.path.join(F4.OUT, "crossfit.npz"))
    z = np.load(FIX.F2C)
    ids, units_w = z["ids"].astype(str), z["units"].astype(str)
    q_win, q_task, q_gold = z["q_win"], z["q_task"].astype(str), z["q_gold"].astype(int)
    states = z["states"]
    e = np.load(FIX.FSEC)
    sm_all, sx_all = e["sec_mean"], e["sec_max"]
    zz = np.load(F4.NOISY_NPZ)
    nids = zz["ids"].astype(str)
    nst, nsm, nsx, ntask = zz["states"], zz["sec_mean"], zz["sec_max"], zz["q_task"].astype(str)
    nreg = zz["regime"].astype(str)
    npos = {w: i for i, w in enumerate(nids)}
    wpos = {w: i for i, w in enumerate(ids)}
    idx = json.load(open(os.path.join(OUT, "train_index.json")))
    changed = set(idx["changed"])
    nl = load_train_nolab()
    assert list(nl["ids"]) == idx["todo"], "the label-free chunks do not hold exactly the planned windows"
    nlpos = {(w, q): j for j, (w, q) in enumerate(zip(nl["win_id"], nl["q_task"]))}
    fold = F4.folds_of(units_w)
    ro, th = R2D.load_2d(), F4.main_th()
    zs = np.load(f"{RO.OUT}/feats_dev_natural.npz")
    zn0 = np.load(os.path.join(OUT, "dev", "natural_nolab.npz"))
    secn = R2D.Sec()
    log = {"folds": K, "epochs": EPOCHS, "main": {}, "scale_on_natural_dev": {}}
    P, P0 = {}, {}
    for q in ("S", "R"):
        m = np.where((q_task == q) & (q_gold >= 0))[0]
        wq = q_win[m]
        win = ids[wq]
        fq = np.array([fold[units_w[i]] for i in wq])
        X = R2D.design(states[m], sm_all[wq], sx_all[wq])
        X -= ro[q]["mu"]
        X /= ro[q]["sd"]
        Xh = X.astype(np.float16)
        del X
        y = q_gold[m]
        has = np.array([w in npos for w in win])
        ni = np.array([npos[w] for w in win[has]], int)
        assert (ntask[ni] == q).all()
        Xn = R2D.design(nst[ni], nsm[ni], nsx[ni])
        Xn -= ro[q]["mu"]
        Xn /= ro[q]["sd"]
        Xnh = Xn.astype(np.float16)
        del Xn
        # label-free inputs of the rows whose text changed (noisy windows with their noisy ears)
        kept = ~(has & (np.array([nreg[npos[w]] if w in npos else "decoupled" for w in win]) == "natural"))
        miss = [w for w, k_ in zip(win, kept) if k_ and w in changed and (w, q) not in nlpos]
        assert not miss, f"{len(miss)} changed windows on kept rows have no label-free forward, e.g. {miss[:3]}"
        ch = np.array([(w in changed) and ((w, q) in nlpos) for w in win])
        ci = np.array([nlpos[(w, q)] for w in win[ch]], int)
        w_ch = win[ch]
        sm0 = np.stack([nsm[npos[w]] if w in npos else sm_all[wpos[w]] for w in w_ch])
        sx0 = np.stack([nsx[npos[w]] if w in npos else sx_all[wpos[w]] for w in w_ch])
        X0 = R2D.design(nl["states"][ci], sm0, sx0)
        del sm0, sx0
        X0 -= ro[q]["mu"]
        X0 /= ro[q]["sd"]
        X0h = X0.astype(np.float16)
        del X0
        # natural dev, standard and label-free, for the scale checks
        mn = np.where(zs["q_task"].astype(str) == q)[0]
        rn = secn.rows(zs["ids"][zs["q_win"][mn]])
        Xd = R2D.design(zs["states"][mn], secn.sm[rn], secn.sx[rn])
        Xd -= ro[q]["mu"]
        Xd /= ro[q]["sd"]
        Xd0 = R2D.design(zn0["states"][mn], secn.sm[rn], secn.sx[rn])
        Xd0 -= ro[q]["mu"]
        Xd0 /= ro[q]["sd"]
        lg_off = Xd @ ro[q]["w"] + float(ro[q]["b"])
        lg_off0 = Xd0 @ ro[q]["w"] + float(ro[q]["b"])
        chn = zn0["changed"][zn0["q_win"][mn]]
        Xdh, Xd0h = Xd.astype(np.float16), Xd0.astype(np.float16)
        del Xd, Xd0
        p_clean, p_noisy, p0 = np.zeros(len(m)), np.zeros(int(has.sum())), np.full(int(ch.sum()), np.nan)
        fc = fq[ch]
        scale = []
        for f in range(K):
            lin = RO.train_logreg(Xh[fq != f], y[fq != f], float(ro[q]["wd"]), epochs=EPOCHS)
            p_clean[fq == f] = RO.predict(lin, Xh[fq == f])
            if (fq[has] == f).any():
                p_noisy[fq[has] == f] = RO.predict(lin, Xnh[fq[has] == f])
            if (fc == f).any():
                p0[fc == f] = RO.predict(lin, X0h[fc == f])
            rf, rf0 = raw_logits(lin, Xdh), raw_logits(lin, Xd0h)
            cf_, cf0 = F4.logit(F4.sigmoid(rf)), F4.logit(F4.sigmoid(rf0))           # clipped as the small models
            co_, co0 = F4.logit(F4.sigmoid(lg_off)), F4.logit(F4.sigmoid(lg_off0))   # see them (code review item 2)
            scale.append({"fold": f,
                          "z_ratio_clipped": _ratio(cf_, co_), "z_ratio_raw": _ratio(rf, lg_off),
                          "dependence_ratio_clipped": _ratio((cf_ - cf0)[chn], (co_ - co0)[chn]),
                          "dependence_ratio_raw": _ratio((rf - rf0)[chn], (lg_off - lg_off0)[chn]),
                          "decision_agreement": float(np.mean((rf >= F4.logit(th[q])) ==
                                                              (lg_off >= F4.logit(th[q]))))})
            del lin
            torch.cuda.empty_cache()
            print(f"crossfit {q} fold {f}: {time.time() - t0:.0f} s; {scale[-1]}", flush=True)
        log["scale_on_natural_dev"][q] = scale
        p_row = p_clean.copy()
        p_row[has] = p_noisy
        p0_row = p_row.copy()                         # unchanged text: the label-free score is the same score
        p0_row[ch] = p0
        nat = has & (np.array([nreg[npos[w]] if w in npos else "decoupled" for w in win]) == "natural")
        p0_row[nat & ~ch] = np.nan                    # natural-label noisy rows: not forwarded, dropped in fit
        log["main"][q] = {"rows": int(len(m)), "label_free_rows": int(ch.sum()),
                          "oof_accuracy_clean_rows": float(np.mean((p_clean[~has] >= th[q]) == (y[~has] == 1)))}
        P[q], P0[q] = p_row, p0_row
        del Xh, Xnh, X0h, Xdh, Xd0h
    rr = {q: np.where((q_task == q) & (q_gold >= 0))[0] for q in ("S", "R")}
    row_p = np.concatenate([P["S"], P["R"]])
    row_p0 = np.concatenate([P0["S"], P0["R"]])
    assert np.array_equal(np.concatenate([ids[q_win[rr[q]]] for q in ("S", "R")]), v4["row_win"].astype(str))
    np.savez(os.path.join(OUT, "crossfit5_main.npz"), row_p=row_p, row_p0=row_p0)    # before the words step
    print(f"fold scores saved ({time.time() - t0:.0f} s)", flush=True)
    # words: cross-fitted P(respond | last line) for the R rows of the used windows
    lines = idx["last_line"]
    row_w = np.full(len(row_p), np.nan)
    rq = v4["row_q"].astype(str)
    use = ~(v4["row_noisy"] & (v4["row_regime"] == "natural"))
    rsel = np.where((rq == "R") & use)[0]
    L = [lines[str(w)] for w in v4["row_win"][rsel]]
    yR = v4["row_gold"][rsel].astype(int)
    fR = np.array([fold[str(u)] for u in v4["row_unit"][rsel]])
    for f in range(K):
        mdl = words_fit([L[i] for i in np.where(fR != f)[0]], yR[fR != f])
        row_w[rsel[fR == f]] = words_p(mdl, [L[i] for i in np.where(fR == f)[0]])
    full = words_fit(L, yR)
    pickle.dump(full, open(os.path.join(OUT, "words.pkl"), "wb"))
    log["words"] = {"rows": int(len(rsel)), "oof_accuracy_at_0.5": float(np.mean((row_w[rsel] >= 0.5) == (yR == 1)))}
    for q in ("S", "R"):
        for name in ("z_ratio_clipped", "dependence_ratio_clipped"):
            r_ = float(np.mean([x[name] for x in log["scale_on_natural_dev"][q]]))
            log["scale_on_natural_dev"][f"{q} {name} mean"] = r_
            log["scale_on_natural_dev"][f"{q} {name} within {SCALE_BAND}"] = bool(SCALE_BAND[0] <= r_ <= SCALE_BAND[1])
    np.savez(os.path.join(OUT, "crossfit5.npz"), row_p=row_p, row_p0=row_p0, row_w=row_w)
    log["seconds"] = time.time() - t0
    json.dump(log, open(os.path.join(OUT, "crossfit5_log.json"), "w"), indent=1)
    print(json.dumps(log, indent=1), flush=True)


# ------------------------------------------------------------------------------------------------ fit

def natural_inputs():
    """Natural dev per question key: main p (standard), p0 (label-free), clarity, notification features, words."""
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    rows_d, rows_by_d = G.load("dev")
    ro = R2D.load_2d()
    zs = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    z0 = dict(np.load(os.path.join(OUT, "dev", "natural_nolab.npz")))
    sec = R2D.Sec()
    main = RD.keyed(R2D.scores_2d(zs, sec, ro))
    main0 = RD.keyed(R2D.scores_2d(z0, sec, ro))
    for i, ch in zip(z0["ids"], z0["changed"]):         # unchanged text: the same score, as in training (review 7)
        if not ch:
            u, v, k = str(i).split("|")
            main0[(u, v, int(k))] = dict(main[(u, v, int(k))])
    cd, _ = FIX2.clarity_of(FIX2.whole(sec.sm, sec.sx), FIX2.load_probe())
    wins = {w["id"]: w for w in D.windows_of(rows_d, "dev")}
    ctx = C.Context("dev")
    words = pickle.load(open(os.path.join(OUT, "words.pkl"), "rb"))
    keys = list(main)
    lines = [last_line(ctx.situation(rows_by_d[(u, v)], k, "full")[0]) for (u, v, k) in keys]
    wv = words_p(words, lines)
    out = {}
    for (u, v, k), wp in zip(keys, wv):
        wid = f"{u}|{v}|{k}"
        out[(u, v, k)] = {"p": main[(u, v, k)], "p0": main0[(u, v, k)], "c": float(cd[sec.pos[wid]]),
                          "F": F4.notif_feats(rows_by_d[(u, v)], wins[wid]), "w": float(wp)}
    return rows_d, out


def natural_scores5(models, th, on, nat=None):
    if nat is None:
        _, nat = natural_inputs()
    out = {}
    for key, x in nat.items():
        if not on:
            out[key] = dict(x["p"])
            continue
        out[key] = {q: float(F4._apply(models["notification"][q], notif_X5(
            [p], [x["p0"][q]], [x["c"]], th[q], [x["F"]], [x["w"]] if q == "R" else None))[0])
            for q, p in x["p"].items()}
    return out


def fit():
    import p1v4_score as S
    v4 = np.load(os.path.join(F4.OUT, "crossfit.npz"))
    cf = np.load(os.path.join(OUT, "crossfit5.npz"))
    rows_by, used = train_used()
    wmap = {w["id"]: w for w in used}
    use = ~(v4["row_noisy"] & (v4["row_regime"] == "natural"))
    assert np.isfinite(cf["row_p0"][use]).all(), "label-free scores missing on rows kept for fitting"
    th = F4.main_th()
    cache = {}

    def feat(wid):
        if wid not in cache:
            w = wmap[wid]
            cache[wid] = F4.notif_feats(rows_by[w["key"]], w)
        return cache[wid]

    models = {"confidence": {}, "confidence_label_free_only": {}, "notification": {}, "main_thresholds": th,
              "knots": KNOTS, "train (in-sample)": {}}
    keep = {}
    for q in ("S", "R"):
        sel = (v4["row_q"].astype(str) == q) & use
        p, p0, c = cf["row_p"][sel], cf["row_p0"][sel], v4["row_c"][sel]
        g = v4["row_gold"][sel].astype(int)
        wq = v4["row_win"][sel].astype(str)
        right = ((p >= th[q]) == (g == 1)).astype(int)
        Xc = conf_X5(p, p0, c, th[q])
        models["confidence"][q] = _lr0(Xc, right)
        models["confidence_label_free_only"][q] = _lr0(conf_X5_free(p, p0, c, th[q]), right)
        F = np.array([feat(w) for w in wq])
        wv = cf["row_w"][sel] if q == "R" else None
        if q == "R":
            assert np.isfinite(wv).all()
        Xn = notif_X5(p, p0, c, th[q], F, wv)
        models["notification"][q] = _lr0(Xn, g)
        pn = F4._apply(models["notification"][q], Xn)
        pr_ = F4._apply(models["confidence"][q], Xc)
        co = np.array(models["confidence"][q]["coef"])
        ratio = {f"knot {k}": float(-co[15 + j] / co[5 + j]) if co[5 + j] != 0 else None
                 for j, k in enumerate(KNOTS)}
        cn = np.array(models["notification"][q]["coef"])
        ratio_n = {f"knot {k}": float(-cn[10 + j] / cn[5 + j]) if cn[5 + j] != 0 else None
                   for j, k in enumerate(KNOTS)}
        keep[q] = (wq, g, pn, F, v4["row_db"][sel])
        models["train (in-sample)"][q] = {
            "rows": int(sel.sum()), "confidence_calibration_by_clarity": F4._calibration(pr_, right, c),
            "push_to_margin_coefficient_ratio (1 = uses the label-free margin)": ratio,
            "notification model: dependence_to_score_coefficient_ratio (1 = uses the label-free score)": ratio_n,
            "dependence |z - z0| mean": float(np.mean(np.abs(zrel(p, th[q]) - zrel(p0, th[q])))),
            "notification_log_loss": float(-np.mean(g * np.log(np.clip(pn, F4.EPS, 1)) +
                                                    (1 - g) * np.log(np.clip(1 - pn, F4.EPS, 1))))}
        print(f"fit {q}: rows {int(sel.sum())}; push/margin ratio by knot {ratio}", flush=True)
    rows_d, nat = natural_inputs()
    op = S.operating_point(rows_d, natural_scores5(models, th, True, nat))
    th5 = {"S": float(op["th_s"]), "R": float(op["th_r"])}
    models["notification_thresholds"] = th5
    models["notification_operating_point"] = {k: op[k] for k in ("th_s", "th_r", "floors_met", "primary",
                                                                  "lowest_floor")}
    for q, part in (("R", "r_hear"), ("S", "s_move")):
        wq, g, pn, F, db = keep[q]
        prt = np.array([wmap[w]["part"] == part for w in wq])
        hasn = F.any(1)
        tab = {}
        for d in (0, 10, 20, 30, 40):
            for h in (True, False):
                s_ = prt & (db == d) & (hasn == h)
                if s_.any():
                    tab[f"+{d} dB, notification {'present' if h else 'absent'}"] = {
                        "n": int(s_.sum()), "accuracy": float(np.mean((pn[s_] >= th5[q]) == (g[s_] == 1)))}
        models["train (in-sample)"][q][f"notification_model_on_{part}"] = tab
    json.dump(models, open(os.path.join(OUT, "models5.json"), "w"), indent=1, default=float)
    print("notification thresholds (natural dev, notifications on):", models["notification_operating_point"],
          flush=True)
    for q in ("R", "S"):
        print(f"train (in-sample) {q}:", json.dumps(models["train (in-sample)"][q], indent=1), flush=True)


# ------------------------------------------------------------------------------------------------ eval

def items_main(zd, sc, th_pair):
    """As p1v4_reliability_fix3.questions3, with the window id and the margin |logit p - logit th| appended."""
    import p1v4_step0_confidence as S0
    out = []
    for j in range(len(zd["q_task"])):
        g = int(zd["q_gold"][j])
        if g < 0:
            continue
        i = int(zd["q_win"][j])
        wid = str(zd["ids"][i])
        u, v, k = wid.split("|")
        q = str(zd["q_task"][j])
        p = sc[(u, v, int(k))][q]
        t_q = th_pair[0] if q == "S" else th_pair[1]
        pos = p >= t_q
        conf_p = (p >= CONF_P) if pos else (p <= 1 - CONF_P)
        out.append((u, str(zd["parts"][i]), q, p, conf_p, S0.confidence(p, t_q) >= 0.5, pos == bool(g), wid,
                    float(abs(F4.logit(p) - F4.logit(t_q)))))
    return out


def v4_conf_scores(zd, sc_main, th, m4, pr):
    """{(window id, task): P(right)} of the version-4 confidence model (notifications unavailable)."""
    c_w, _ = FIX2.clarity_of(FIX2.whole(zd["sec_mean"], zd["sec_max"]), pr)
    out = {}
    for j in range(len(zd["q_task"])):
        if int(zd["q_gold"][j]) < 0:
            continue
        i = int(zd["q_win"][j])
        wid = str(zd["ids"][i])
        u, v, k = wid.split("|")
        q = str(zd["q_task"][j])
        p = sc_main[(u, v, int(k))][q]
        out[(wid, q)] = float(F4._apply(m4["confidence"][q], F4.conf_X([p], [float(c_w[i])], th[q]))[0])
    return out


def items5(zd, z0d, sc_main, sc0, th, models, th5, on, rows_by, wins, pr, words_of, which="confidence"):
    """[(unit, part, task, p, confident, confident, right, window id, score)]; score = the confidence model's P(right)
    (notifications unavailable) or the probability of the chosen answer (notifications on)."""
    c_w, _ = FIX2.clarity_of(FIX2.whole(zd["sec_mean"], zd["sec_max"]), pr)
    out = []
    for j in range(len(zd["q_task"])):
        g = int(zd["q_gold"][j])
        if g < 0:
            continue
        i = int(zd["q_win"][j])
        wid = str(zd["ids"][i])
        u, v, k = wid.split("|")
        q = str(zd["q_task"][j])
        key = (u, v, int(k))
        p, p0, c = sc_main[key][q], sc0[key][q], float(c_w[i])
        if on:
            f = F4.notif_feats(rows_by[(u, v)], wins[wid])
            wv = [words_of[wid]] if q == "R" else None
            pp = float(F4._apply(models["notification"][q], notif_X5([p], [p0], [c], th[q], [f], wv))[0])
            pos = pp >= th5[q]
            score = pp if pos else 1 - pp
        else:
            pp = p
            pos = p >= th[q]
            X = (conf_X5 if which == "confidence" else conf_X5_free)([p], [p0], [c], th[q])
            score = float(F4._apply(models[which][q], X)[0])
        out.append((u, str(zd["parts"][i]), q, pp, bool(score >= CONF_P), bool(score >= CONF_P), pos == bool(g),
                    wid, score))
    return out


def eval_():
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    import p1v4_reliability_dev as RD
    import p1v4_score as S
    models, m4 = load_models(), F4.load_models()
    th = F4.main_th()
    th5, th4 = models["notification_thresholds"], m4["notification_thresholds"]
    st = RD.rehearsal_settings()
    ths = {"2d": (th["S"], th["R"]), "old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])}
    ro2d, pr = R2D.load_2d(), FIX2.load_probe()
    rows_d, rows_by, groups, gw = dev_grid()
    wins = {w["id"]: w for w in gw}
    cov = {g["unit"]: F3.covered(g, rows_by) for g in groups}
    words = pickle.load(open(os.path.join(OUT, "words.pkl"), "rb"))
    ctx_none = G.matched_context(C.Context)("dev", groups, "none", rows_by, final=False)
    words_of = dict(zip([w["id"] for w in gw], words_p(words, [last_line(ctx_none.situation(
        rows_by[(w["unit"], w["version"])], w["k"], "full")[0]) for w in gw])))
    res = {"split": "dev", "note": "exploratory (evidence-reliability step 5, version 5)",
           "thresholds": {"main": th, "notification model v5": th5, "notification model v4": th4},
           "notification_operating_point": models["notification_operating_point"],
           "confident": f"probability of the chosen answer >= {CONF_P}", "cells": {}, "natural": {}, "criteria": {},
           "report": {}}
    Q = {}

    def subsets(qs, part):
        out = {"all": [x for x in qs if x[1] == part]}
        out["covered"] = [x for x in out["all"] if cov[x[0]]]
        out["not covered"] = [x for x in out["all"] if not cov[x[0]]]
        return {k_: v for k_, v in out.items() if v}

    conds = dict(CONDS, T_off_truth=(False, "truth"))
    dep_of = {}
    for lv in LEVELS:
        zs = {c: dict(np.load(f"{FIX.REL_DEV}/{lv}/l1_{c}.npz")) for c in ("none", "c0.99", "mv0.99", "truth")}
        z0 = dict(np.load(os.path.join(OUT, "dev", lv, "l1_nolab.npz")))
        sec0 = R2D.Sec(None, z0["ids"], z0["sec_mean"], z0["sec_max"])
        sc0 = RD.keyed(R2D.scores_2d(z0, sec0, ro2d))
        for cond, (on, lab) in conds.items():
            parts_z = {"none": [zs["none"]], "fake": [zs["c0.99"], zs["mv0.99"]], "truth": [zs["truth"]]}[lab]
            qs = {n: [] for n in ("2d", "old head", "rel v4", "rel v5", "rel v5 label-free only")}
            for zd in parts_z:
                sec = R2D.Sec(None, zd["ids"], zd["sec_mean"], zd["sec_max"])
                sc_main = RD.keyed(R2D.scores_2d(zd, sec, ro2d))
                for j in range(len(zd["q_task"])):
                    if int(zd["q_gold"][j]) < 0:
                        continue
                    wid = str(zd["ids"][int(zd["q_win"][j])])
                    u, v, k = wid.split("|")
                    q = str(zd["q_task"][j])
                    dep_of[(lv, cond, wid, q)] = float(zrel(sc_main[(u, v, int(k))][q], th[q]) -
                                                       zrel(sc0[(u, v, int(k))][q], th[q]))
                qs["2d"] += items_main(zd, sc_main, ths["2d"])
                qs["old head"] += F3.questions3(zd, RD.keyed(RO.scores_of(zd, None, None)), ths["old head"])
                v4s = {} if on else v4_conf_scores(zd, sc_main, th, m4, pr)
                qs["rel v4"] += [x + (v4s.get((x[7], x[2])),)
                                 for x in F4.items_v4(zd, sc_main, th, m4, th4, on, rows_by, wins, pr)]
                qs["rel v5"] += items5(zd, z0, sc_main, sc0, th, models, th5, on, rows_by, wins, pr, words_of)
                if not on:
                    qs["rel v5 label-free only"] += items5(zd, z0, sc_main, sc0, th, models, th5, False, rows_by,
                                                           wins, pr, words_of, "confidence_label_free_only")
            for n, qq in qs.items():
                for part in ("r_hear", "s_move"):
                    for sub, sel in subsets(qq, part).items():
                        Q[(part, cond, n, lv, sub)] = sel
                        s_ = F3.stats(sel)
                        if n.startswith("rel"):
                            s_.pop("confident_share_threshold_distance")
                            s_.pop("confident_error_rate_threshold_distance")
                        s_["group_all_right"] = float(np.mean(list(F3.all_right(sel).values())))
                        res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {}).setdefault(
                            sub, {})[lv] = s_
    # version 4 recomputed here must reproduce its stored result (code review 12)
    r4 = json.load(open("results/main_v04/reliability_step4_dev.json"))["cells"]
    worst4 = max(abs(res["cells"][p][c]["rel v4"]["all"][lv][m_] - r4[p][c]["rel v4"]["all"][lv][m_])
                 for p in ("r_hear", "s_move") for c in CONDS for lv in LEVELS for m_ in ("accuracy", "confident_share"))
    assert worst4 < 1e-12, f"version 4 does not reproduce its stored cells (max diff {worst4})"
    # natural dev: decisions without notifications are the main system's; with notifications, the version-5 model
    gmap = S.load_groups("dev")
    _, nat = natural_inputs()
    zg = np.load(f"{RO.OUT}/feats_dev_natural.npz")
    gold_nat = {}
    for wi, q, g in zip(zg["ids"][zg["q_win"]], zg["q_task"], zg["q_gold"]):
        if int(g) >= 0:
            u, v, k = str(wi).split("|")
            gold_nat[((u, v, int(k)), str(q))] = int(g)
    nat_main = natural_scores5(models, th, False, nat)
    for name, sc, t_ in (("2d, standard", nat_main, (th["S"], th["R"])),
                         ("rel v5, notifications unavailable", nat_main, (th["S"], th["R"])),
                         ("rel v5, notifications on", natural_scores5(models, th, True, nat), (th5["S"], th5["R"]))):
        m_ = S.metrics(S.unit_table(rows_d, S.decide(sc, *t_), gmap))
        res["natural"][name] = {"primary": m_["primary"], "parts": m_["parts"], "floors": m_["floors"]}

    def acc_fn(sel):
        return float(np.mean([x[6] for x in sel])) if sel else None

    def cer_fn(sel):
        cp = [x for x in sel if x[4]]
        return float(np.mean([not x[6] for x in cp])) if cp else None

    def share_fn(sel):
        return float(np.mean([x[4] for x in sel]))

    def judge(point, ci, bar, higher=True):
        ok = point is None or (point >= bar if higher else point <= bar)
        unclear = ci is not None and ci[0] <= bar <= ci[1]
        return {"pass": bool(ok), "unclear": bool(unclear)}

    def event_member(x):
        return wins[x[7]]["gold"][x[2]] == ("not" if x[2] == "R" else "stop")

    crit = {}
    c1 = {}
    for p in ("r_hear", "s_move"):
        for lv in ("dnoise20", "dnoise30", "dnoise40"):
            sel = Q[(p, "A_on_none", "rel v5", lv, "covered")]
            v, ci = acc_fn(sel), F3.boot(sel, acc_fn)
            ev = [x for x in sel if event_member(x)]
            ne = [x for x in sel if not event_member(x)]
            c1[f"{p} {lv}"] = {"accuracy": v, "ci95": ci, "event members": acc_fn(ev), "n event": len(ev),
                               "no-event members": acc_fn(ne), "n no-event": len(ne), **judge(v, ci, 0.95)}
    crit["1 notifications on, ears bad, covered events: accuracy >= 0.95"] = c1
    c2 = {}
    for p in ("r_hear", "s_move"):
        for lv in LEVELS:
            sel = Q[(p, "B_on_fake", "rel v5", lv, "covered")]
            v, ci = acc_fn(sel), F3.boot(sel, acc_fn)
            ev = [x for x in sel if event_member(x)]
            ne = [x for x in sel if not event_member(x)]
            c2[f"{p} {lv}"] = {"accuracy": v, "ci95": ci, "event members": acc_fn(ev), "n event": len(ev),
                               "no-event members": acc_fn(ne), "n no-event": len(ne), **judge(v, ci, 0.95)}
    crit["2 notifications on vs fake detector labels, covered events: accuracy >= 0.95"] = c2
    c3 = {}
    for p in ("r_hear", "s_move"):
        a_new = F3.all_right(Q[(p, "C_off_fake", "rel v5", "dclean", "all")])
        a_ref = F3.all_right(Q[(p, "C_off_fake", "2d", "dclean", "all")])
        gap_items = [(u, None, None, None, None, None, a_new[u] - a_ref[u]) for u in sorted(a_new)]
        gap = float(np.mean([x[6] for x in gap_items]))
        ci = F3.boot(gap_items, lambda sel: float(np.mean([x[6] for x in sel])))
        c3[p] = {"rel v5": float(np.mean(list(a_new.values()))), "main system": float(np.mean(list(a_ref.values()))),
                 "gap": gap, "ci95": ci, "by construction": True, **judge(gap, ci, -0.05)}
    crit["3 notifications unavailable, fake labels, clean: group all-right within 5 points of the main system"] = c3
    c4 = {}
    for p in ("r_hear", "s_move"):
        for c in ("C_off_fake", "D_off_none"):
            for lv in ("dnoise30", "dnoise40"):
                sel = Q[(p, c, "rel v5", lv, "all")]
                v, ci = cer_fn(sel), F3.boot(sel, cer_fn)
                nc = int(sum(x[4] for x in sel))
                c4[f"{p} {c} {lv}"] = {"confident_error_rate": v, "n_confident": nc, "n": len(sel), "ci95": ci,
                                       **({"note": "no confident decisions (fewer than 30)"} if nc < FEW else {}),
                                       **judge(v, ci, 0.10, higher=False)}
    crit["4 notifications unavailable, ears bad: confident errors <= 10%"] = c4
    c4b = {}
    for p in ("r_hear", "s_move"):
        sel = Q[(p, "D_off_none", "rel v5", "dclean", "all")]
        ref = Q[(p, "D_off_none", "2d", "dclean", "all")]
        v, r_ = share_fn(sel), share_fn(ref)
        ci = F4.boot_pair(sel, ref, share_fn)
        c4b[p] = {"rel v5": v, "main system": r_, "difference": v - r_, "ci95_difference": ci,
                  **judge(v - r_, ci, -0.10)}
    crit["4' notifications unavailable, no labels, clean: confident share within 10 points of the main system"] = c4b
    nn = res["natural"]["rel v5, notifications unavailable"]["primary"]
    nm = res["natural"]["2d, standard"]["primary"]
    crit["5 natural dev: five-part mean within 3 points of the main system"] = {
        "all": {"rel v5": nn, "main system": nm, "gap": nn - nm, "by construction": True,
                **judge(nn - nm, None, -0.03)}}
    c6 = {}
    for c in ("A_on_none", "B_on_fake"):
        for lv in ("dnoise30", "dnoise40"):
            sel = Q[("r_hear", c, "rel v5", lv, "not covered")]
            v, ci = cer_fn(sel), F3.boot(sel, cer_fn)
            nc = int(sum(x[4] for x in sel))
            c6[f"r_hear knock {c} {lv}"] = {"confident_error_rate": v, "n_confident": nc, "n": len(sel), "ci95": ci,
                                            **({"note": "no confident decisions (fewer than 30)"} if nc < FEW else {}),
                                            **judge(v, ci, 0.10, higher=False)}
    crit["6 notifications on, knock (not covered), ears bad: confident errors <= 10%"] = c6
    for k_, cells in crit.items():
        res["criteria"][k_] = {"cells": cells, "pass": all(v["pass"] for v in cells.values()),
                               "unclear": any(v["unclear"] for v in cells.values())}
    assert abs(nn - nm) < 1e-12 and all(abs(v["gap"]) < 1e-12 for v in c3.values()), "construction check"
    # report: matched coverage and AUROC without notifications (main margin, v4, v5, v5 label-free only)
    rep = {}
    pooled = collections.defaultdict(lambda: collections.defaultdict(list))
    for p in ("r_hear", "s_move"):
        for c in ("C_off_fake", "D_off_none", "T_off_truth"):
            for lv in LEVELS:
                main_, v4_, v5_, vf_ = (Q[(p, c, n, lv, "all")] for n in ("2d", "rel v4", "rel v5",
                                                                           "rel v5 label-free only"))
                keys_ = [(x[7], x[2]) for x in main_]
                assert keys_ == [(x[7], x[2]) for x in v4_] == [(x[7], x[2]) for x in v5_] == \
                    [(x[7], x[2]) for x in vf_], "question order differs between systems"
                assert all(x[6] == y[6] for x, y in zip(main_, v5_)), "decisions differ without notifications"
                right = np.array([x[6] for x in main_])
                sc = {"main margin": np.array([x[8] for x in main_]), "rel v4": np.array([x[8] for x in v4_]),
                      "rel v5": np.array([x[8] for x in v5_]), "rel v5 label-free only": np.array([x[8] for x in vf_])}
                n5 = int(sum(x[4] for x in v5_))
                n4 = int(sum(x[4] for x in v4_))
                cell = {"n": len(right), "n_confident_v5": n5, "n_confident_v4": n4}
                for name, s in sc.items():
                    order = np.argsort(-s, kind="mergesort")
                    cell[name] = {"auroc": auroc(s, right),
                                  "error_at_v5_coverage": float(1 - right[order[:n5]].mean()) if n5 else None,
                                  "error_at_v4_coverage": float(1 - right[order[:n4]].mean()) if n4 else None}
                    pooled[(p, c)][name].append((s, right))
                rep[f"{p} {c} {lv}"] = cell
    for (p, c), d in pooled.items():
        rep[f"{p} {c} pooled over levels"] = {name: {"auroc": auroc(np.concatenate([a for a, _ in v]),
                                                                    np.concatenate([b for _, b in v]))}
                                              for name, v in d.items()}
    res["report"]["coverage_and_auroc_without_notifications"] = rep
    # report: over-suspicion (confident share at clean: fake labels, truth labels; natural dev) and truth-label cost
    over = {}
    for p in ("r_hear", "s_move"):
        for c in ("C_off_fake", "T_off_truth", "D_off_none"):
            over[f"{p} {c} clean"] = {n: share_fn(Q[(p, c, n, "dclean", "all")]) for n in ("2d", "rel v4", "rel v5")}
    res["report"]["confident_share_at_clean"] = over
    cost = {}
    for p in ("r_hear", "s_move"):
        for lv in LEVELS:
            cost[f"{p} {lv}"] = {n: {"accuracy": acc_fn(Q[(p, "T_off_truth", n, lv, "all")]),
                                     "confident_share": share_fn(Q[(p, "T_off_truth", n, lv, "all")]),
                                     "confident_error_rate": cer_fn(Q[(p, "T_off_truth", n, lv, "all")])}
                                 for n in ("2d", "rel v4", "rel v5")}
    res["report"]["truth_label_cells"] = cost
    # report (code review 4): label dependence by condition and level; natural dev confident share without
    # notifications; natural dev questions with a phone or doorbell notification, accuracy by gold answer
    dep = {}
    for p in ("r_hear", "s_move"):
        for c in ("D_off_none", "C_off_fake", "T_off_truth"):
            for lv in LEVELS:
                xs = Q[(p, c, "rel v5", lv, "all")]
                dz = np.array([abs(dep_of[(lv, c, x[7], x[2])]) for x in xs])
                dep[f"{p} {c} {lv}"] = {"mean |z - z0|": float(dz.mean()), "share > 0.5": float(np.mean(dz > 0.5))}
    res["report"]["label_dependence_on_dev"] = dep
    m4c = m4["confidence"]
    nat_share = {"main (own probability)": [], "rel v4": [], "rel v5": []}
    ring = collections.defaultdict(lambda: collections.defaultdict(list))
    nat_v4 = F4.natural_scores(m4, th, True)
    nat_v5 = natural_scores5(models, th, True, nat)
    for key, x in nat.items():
        for q, p_ in x["p"].items():
            pos = p_ >= th[q]
            nat_share["main (own probability)"].append((p_ >= CONF_P) if pos else (p_ <= 1 - CONF_P))
            nat_share["rel v4"].append(float(F4._apply(m4c[q], F4.conf_X([p_], [x["c"]], th[q]))[0]) >= CONF_P)
            nat_share["rel v5"].append(float(F4._apply(models["confidence"][q], conf_X5(
                [p_], [x["p0"][q]], [x["c"]], th[q]))[0]) >= CONF_P)
            if q == "R" and any(x["F"][:8]):                       # a phone or doorbell notification (any bin)
                g = gold_nat.get((key, q))
                if g is None:
                    continue
                ring[g]["main"].append((p_ >= th["R"]) == bool(g))
                ring[g]["rel v4"].append((nat_v4[key][q] >= th4["R"]) == bool(g))
                ring[g]["rel v5"].append((nat_v5[key][q] >= th5["R"]) == bool(g))
    res["report"]["natural_confident_share_without_notifications"] = {k_: float(np.mean(v))
                                                                      for k_, v in nat_share.items()}
    res["report"]["natural_ring_questions_accuracy_by_gold"] = {
        f"gold {'respond' if g else 'not'}": {n: {"n": len(v), "accuracy": float(np.mean(v))} for n, v in d.items()}
        for g, d in ring.items()}
    res["report"]["crossfit"] = json.load(open(os.path.join(OUT, "crossfit5_log.json")))
    res["report"]["forward"] = json.load(open(os.path.join(OUT, "forward_log.json")))
    json.dump(res, open("results/main_v04/reliability_step5_dev.json", "w"), indent=1, default=float)
    print("thresholds:", json.dumps(res["thresholds"]))
    print("notification operating point:", json.dumps(res["notification_operating_point"], default=float))
    print("natural:", json.dumps({k_: round(v["primary"], 3) for k_, v in res["natural"].items()}))
    for k_, v in res["criteria"].items():
        print(f"CRITERION {k_}: {'PASS' if v['pass'] else 'FAIL'}{' (unclear)' if v['unclear'] else ''}")
        for ck, cv in v["cells"].items():
            print("   ", ck, json.dumps({a: (round(b, 3) if isinstance(b, float) else
                                            [round(x, 3) for x in b] if isinstance(b, list) else b)
                                         for a, b in cv.items()}))
    print("== matched coverage (error of each score's top-n, n = version 5's confident count) and AUROC")
    for k_, v in rep.items():
        print(f"  {k_:40s} " + " | ".join(
            f"{n}: " + (f"{x['auroc']:.3f}" if x.get("auroc") is not None else "n/a") +
            (f" err {x['error_at_v5_coverage']:.3f}" if x.get("error_at_v5_coverage") is not None else "")
            for n, x in v.items() if isinstance(x, dict)))
    print("== confident share at clean:", json.dumps({k_: {n: round(x, 3) for n, x in v.items()}
                                                     for k_, v in over.items()}))
    for part, cs in res["cells"].items():
        for cond, ns in cs.items():
            print(f"== {part} / {cond} (all groups): accuracy | group all-right | confident share | confident errors")
            for n, subs in ns.items():
                cells = []
                for lv, x in subs["all"].items():
                    ce = "n/a" if x["confident_error_rate"] is None else f"{x['confident_error_rate']:.3f}"
                    cells.append(f"{lv[1:]}: {x['accuracy']:.3f} {x['group_all_right']:.3f} "
                                 f"{x['confident_share']:.3f} {ce}")
                print(f"  {n:22s} " + " | ".join(cells))
    print("-> results/main_v04/reliability_step5_dev.json")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    fn = {"smoke": smoke, "forward": forward, "crossfit": crossfit, "fit": fit, "eval": eval_}.get(cmd)
    if fn is None:
        raise SystemExit(__doc__)
    fn()
